def fmt(i):
    rows = SRC.get(i, [])
    out = []
    for r in rows:
        s = r["src"]
        if r["url"]: s += f" — {r['url']}"
        s += f". Фрагмент: {r['fragment']}. [{r['access']}]"
        out.append(s)
    return "\n".join(out)
